import ast

# Parse the code
tree = ast.parse(code)

# Find the if statement
if_stmt = None
for node in ast.walk(tree):
    if isinstance(node, ast.If):
        if_stmt = node
        break

assert if_stmt is not None, 'No if statement found'

# Check conditions are in descending order
conditions = []
current = if_stmt
while current:
    # Extract the condition
    if hasattr(current, 'test'):
        # Convert condition to string for checking
        condition_str = ast.unparse(current.test) if hasattr(ast, 'unparse') else str(current.test)
        conditions.append(condition_str)

    # Move to elif or else
    if current.orelse and len(current.orelse) > 0:
        if isinstance(current.orelse[0], ast.If):
            current = current.orelse[0]
        else:
            break
    else:
        break

# Check that conditions are in descending order (>= 90, >= 80, >= 70, >= 60)
# This is a simple check - we look for the pattern in the strings
for i, cond in enumerate(conditions):
    if i < len(conditions) - 1:  # Not the last condition
        # The thresholds should be decreasing: 90, 80, 70, 60
        if '90' in cond and '80' not in cond:
            continue  # Good
        elif '80' in cond and '90' not in cond:
            continue  # Good
        elif '70' in cond and '80' not in cond:
            continue  # Good
        elif '60' in cond and '70' not in cond:
            continue  # Good

print('TEST_PASSED: Conditions are in correct order')
